from fractions import Fraction

def calculate_S(N, M):
    # First sum (A_N)
    A_N = Fraction(0)
    for n in range(1, N + 1):
        numerator = M**n
        denominator = 1
        for k in range(1, n + 1):
            denominator *= (M + k)
        A_N += Fraction(numerator, denominator)

    # Second sum (B_N)
    B_N = Fraction(0)
    for n in range(1, N + 1):
        term = 1
        for k in range(1, n + 1):
            term *= (1 - k/M)
        B_N += term

    return A_N - B_N

M = 2025
N_values = [1, 2, 3, 4, 5]
results = {}

for N in N_values:
    results[N] = calculate_S(N, M)

print("Results for N=1 to N=5:")
for N, result in results.items():
    print(f"N={N}: {result}")
